cd /tmp && python3 -c "
import json,re
ms=[json.loads(l) for l in open('Medication.ndjson')]
names={}
for m in ms:
    nm=None
    for i in m.get('identifier',[]):
        if i['system'].endswith('medication-name'): nm=i['value']
    names[m['id']]=nm
json.dump(names,open('medname.json','w'))
kw=['warfarin','coumadin','apixaban','eliquis','rivaroxaban','xarelto','dabigatran','pradaxa','edoxaban','savaysa','heparin','enoxaparin','lovenox','fondaparinux','argatroban','bivalirudin','dalteparin','lepirudin','desirudin','betrixaban']
s=set()
for k,v in names.items():
    if v and any(w in v.lower() for w in kw): s.add(v)
for v in sorted(s): print(v)
"

