import json,base64,collections,re
ds=[json.loads(l) for l in open('DocumentReference.ndjson')]
narrow=re.compile(r'anticoag|warfarin|apixaban|rivaroxaban|dabigatran|edoxaban|heparin|INR|atrial|fibrillat|flutter|ECG|EKG|QT|bleed|hemorrhag|melena|hematochezia|hematuria|amiodarone|sotalol|dofetilide|citalopram|escitalopram|haloperidol|methadone|pace|pacing|rhythm',re.I)
by=collections.defaultdict(list)
for d in ds:
    txt=base64.b64decode(d['content'][0]['attachment']['data']).decode()
    if d['type']['coding'][0]['display']=='Summary note': continue
    pid=d.get('subject',{}).get('reference','').split('/')[-1]
    by[pid].append((d,txt))
out=open('notes_n.txt','w')
pts={p['id']:p for p in json.load(open('patients.json'))['resources']}
for pid,l in sorted(by.items()):
    l.sort(key=lambda x:x[0]['date'])
    p=pts.get(pid,{})
    hits=[]
    for d,txt in l:
        lines=[ln for ln in txt.split('\n') if narrow.search(ln)]
        if lines: hits.append((d,lines))
    lastmed=None
    for d,txt in l:
        for ln in txt.split('\n'):
            if ln.startswith('Current medications'): lastmed=(d['date'][:10],ln)
    out.write('#'*70+'\nPATIENT %s mrn=%s %s dob=%s died=%s notes=%d\n'%(pid,p.get('identifier',[{}])[0].get('value'),p.get('gender'),p.get('birthDate'),p.get('deceasedDateTime'),len(l)))
    if lastmed: out.write('LAST MEDS (%s): %s\n'%lastmed)
    for d,lines in hits:
        role=[e['valueCode'] for e in d.get('extension',[]) if e['url'].endswith('author-role')]
        enc=d.get('context',{}).get('encounter',[{}])[0].get('reference','').split('/')[-1]
        out.write('NOTE %s %s %s %s %s enc=%s\n'%(d['id'],d['date'][:16],d['type']['coding'][0]['display'][:5],d.get('author',[{}])[0].get('display'),role,enc))
        for ln in lines: out.write('   '+ln+'\n')
out.close()
"; wc -c notes_n.txt

