        if prh=='ATRIAL_FLUTTER' and rh!='ATRIAL_FLUTTER': ch.append('RESOLVED_ATRIAL_FLUTTER')
        pcond=[]
        if p['qrs_ms']>=120: pcond.append('BBB')
        if r['qrs_ms']>=120 and not pcond: ch.append('NEW_BUNDLE_BRANCH_BLOCK')
        if pcond and r['qrs_ms']<120: ch.append('RESOLVED_BUNDLE_BRANCH_BLOCK')
        d=r['qtc_ms']-p['qtc_ms']
        if d>=60: ch.append('QTC_INCREASE_60')
        if d<=-60: ch.append('QTC_DECREASE_60')
    print('%s | %s | ecg=%s %s | prior=%s %s | rhythm=%s rate=%d PR=%s QRS=%d QTc=%d axis=%s(%.0f) cond=%s changes=%s | prevQTc=%s prevQRS=%s'%(
        pts[pid]['identifier'][0]['value'],pid,cur['ecg'],cur['time'],
